     1|/**
     2| * IVX Smart Voice Call Brain — v1.0.0
     3| *
     4| * ChatGPT-level conversation engine for voice calls. Provides:
     5| *   1. Conversation memory — tracks full Q&A history per CallSid
     6| *   2. Context-aware responses — passes prior turns to the AI brain
     7| *   3. Smart system prompt — acts as a capable, knowledgeable assistant
     8| *   4. Conversation lifecycle — auto-cleanup after call ends or timeout
     9| *
    10| * The brain remembers what was said earlier in the call, can reference
    11| * previous answers, maintain topic continuity, and handle follow-up
    12| * questions naturally — just like ChatGPT's conversation mode.
    13| */
    14|
    15|import { requestIVXAIText, isIVXAIConfigured } from '../ivx-ai-runtime';
    16|
    17|export const IVX_VOICE_BRAIN_MARKER = 'ivx-voice-brain-v1.0.0-2026-08-17';
    18|export const IVX_VOICE_BRAIN_VERSION = '1.0.0';
    19|
    20|// ── Types ─────────────────────────────────────────────────────────────────────
    21|
    22|export type ConversationRole = 'user' | 'assistant';
    23|
    24|export type ConversationTurn = {
    25|  role: ConversationRole;
    26|  content: string;
    27|  timestamp: number;
    28|  turnIndex: number;
    29|};
    30|
    31|export type ConversationSession = {
    32|  callSid: string;
    33|  turns: ConversationTurn[];
    34|  startedAt: number;
    35|  lastActivityAt: number;
    36|  topicContext: string | null;
    37|  totalTurns: number;
    38|};
    39|
    40|export type SmartVoiceResult = {
    41|  answer: string;
    42|  ok: boolean;
    43|  error: string | null;
    44|  turnCount: number;
    45|  hadContext: boolean;
    46|  topicDetected: string | null;
    47|  durationMs: number;
    48|};
    49|
    50|// ── In-memory conversation store ──────────────────────────────────────────────
    51|
    52|const MAX_SESSIONS = 100;
    53|const SESSION_TTL_MS = 30 * 60 * 1000; // 30 minutes
    54|const MAX_TURNS_PER_SESSION = 30;
    55|const MAX_CONTEXT_TURNS = 10; // Last 10 turns passed as context
    56|
    57|const sessions = new Map<string, ConversationSession>();
    58|
    59|/** Clean up expired sessions. */
    60|function cleanupExpiredSessions(): void {
    61|  const now = Date.now();
    62|  for (const [sid, session] of sessions) {
    63|    if (now - session.lastActivityAt > SESSION_TTL_MS) {
    64|      sessions.delete(sid);
    65|    }
    66|  }
    67|}
    68|
    69|/** Get or create a conversation session for a CallSid. */
    70|export function getOrCreateSession(callSid: string): ConversationSession {
    71|  cleanupExpiredSessions();
    72|
    73|  let session = sessions.get(callSid);
    74|  if (!session) {
    75|    // Evict oldest session if at capacity
    76|    if (sessions.size >= MAX_SESSIONS) {
    77|      let oldestSid: string | null = null;
    78|      let oldestTime = Infinity;
    79|      for (const [sid, s] of sessions) {
    80|        if (s.lastActivityAt < oldestTime) {
    81|          oldestTime = s.lastActivityAt;
    82|          oldestSid = sid;
    83|        }
    84|      }
    85|      if (oldestSid) sessions.delete(oldestSid);
    86|    }
    87|
    88|    session = {
    89|      callSid,
    90|      turns: [],
    91|      startedAt: Date.now(),
    92|      lastActivityAt: Date.now(),
    93|      topicContext: null,
    94|      totalTurns: 0,
    95|    };
    96|    sessions.set(callSid, session);
    97|  }
    98|  return session;
    99|}
   100|
   101|/** End and remove a conversation session. */
   102|export function endSession(callSid: string): void {
   103|  sessions.delete(callSid);
   104|}
   105|
   106|/** Get conversation stats for a session. */
   107|export function getSessionStats(callSid: string): { exists: boolean; turns: number; durationMs: number } | null {
   108|  const session = sessions.get(callSid);
   109|  if (!session) return null;
   110|  return {
   111|    exists: true,
   112|    turns: session.totalTurns,
   113|    durationMs: Date.now() - session.startedAt,
   114|  };
   115|}
   116|
   117|/** Get all active sessions (for status endpoint). */
   118|export function getActiveSessionStats(): { activeSessions: number; totalTurns: number } {
   119|  cleanupExpiredSessions();
   120|  let totalTurns = 0;
   121|  for (const session of sessions.values()) {
   122|    totalTurns += session.totalTurns;
   123|  }
   124|  return { activeSessions: sessions.size, totalTurns };
   125|}
