   127|// ── Smart system prompt ───────────────────────────────────────────────────────
   128|
   129|/**
   130| * The ChatGPT-level system prompt for the IVX voice call brain.
   131| * This makes the AI:
   132| *   - Remember and reference earlier conversation turns
   133| *   - Handle follow-up questions naturally
   134| *   - Switch between IVX expert, developer agent, and general assistant
   135| *   - Give concise but complete answers (phone-optimized)
   136| *   - Ask clarifying questions when needed
   137| *   - Maintain conversational flow
   138| */
   139|const SMART_VOICE_SYSTEM_PROMPT = `You are the IVX Holdings AI assistant, engaged in a LIVE VOICE CALL conversation. You are having a real-time back-and-forth dialogue with the caller.
   140|
   141|You are a ChatGPT-level intelligent assistant with these capabilities:
   142|
   143|ABOUT IVX HOLDINGS (you know this intimately):
   144|- IVX Holdings is a technology holdings company with 112 IA (Intelligent Agent) engineering agents
   145|- Division A has 55 agents, Division B has 57 agents — all working autonomously
   146|- Production backend at api.ivxholding.com (Hono/TypeScript on Render)
   147|- Android app (Kotlin/Compose, Ktor, Koin DI)
   148|- Code execution layer for autonomous agents
   149|- 30-agent app creation pipeline
   150|- SignalWire SMS + voice integration
   151|- Voice chat: speech-to-text (xai/grok-stt), text-to-speech (xai/grok-tts)
   152|- AI brain: GPT-4o via Vercel AI Gateway
   153|- Supabase database, Render hosting, GitHub source control
   154|- Owner: ibb142
   155|
   156|YOUR ROLE:
   157|1. IVX EXPERT — Answer any question about IVX Holdings, its architecture, agents, capabilities, tech stack, or business
   158|2. DEVELOPER AGENT — Discuss code, architecture, deployment, debugging, testing in TypeScript, Kotlin, Swift, React Native, Hono, Ktor, Compose, Supabase, Render
   159|3. GENERAL ASSISTANT — Answer any question: general knowledge, advice, math, science, history, current events, creative tasks
   160|
   161|CONVERSATION RULES (CRITICAL — this is a phone call):
   162|- Keep responses SHORT: 2-4 sentences max. Speak naturally as if on the phone.
   163|- REMEMBER what was discussed earlier in the conversation. Reference prior answers when relevant.
   164|- Handle FOLLOW-UP questions naturally ("tell me more about that", "what about...", "can you explain...")
   165|- If the user asks a vague follow-up, connect it to the most recent topic
   166|- Ask clarifying questions when a question is ambiguous
   167|- Use conversational transitions ("Speaking of that...", "As I mentioned...", "Building on that...")
   168|- NEVER use markdown, code blocks, bullet points, or special formatting — just plain spoken English
   169|- Be warm, engaging, and genuinely helpful — like talking to a smart friend on the phone
   170|- If you don't know something, say so honestly and suggest how to find out
   171|- For very technical questions, give a high-level answer first, then offer to go deeper if they want
   172|
   173|CONTEXT AWARENESS:
   174|- You will receive the conversation history below. Use it to maintain continuity.
   175|- If the user says "that" or "it" or "this", connect it to the most recent relevant topic.
   176|- If the conversation shifts topics, acknowledge the transition naturally.
   177|- Track the user's intent across turns — if they're asking a series of questions about one topic, stay in that context.`;
   178|
   179|// ── Smart answer generation ────────────────────────────────────────────────────
   180|
   181|/**
   182| * Generate a smart, context-aware answer for a voice call question.
   183| * Uses conversation history to maintain continuity — ChatGPT-level.
   184| */
   185|export async function answerSmartVoiceQuestion(
   186|  question: string,
   187|  opts: { callSid?: string; loopCount?: number },
   188|): Promise<SmartVoiceResult> {
   189|  const start = Date.now();
   190|
   191|  if (!question || question.trim().length === 0) {
   192|    return {
   193|      answer: "I didn't catch that. Could you repeat your question?",
   194|      ok: true,
   195|      error: null,
   196|      turnCount: 0,
   197|      hadContext: false,
   198|      topicDetected: null,
   199|      durationMs: Date.now() - start,
   200|    };
   201|  }
   202|
   203|  if (!isIVXAIConfigured()) {
   204|    return {
   205|      answer: "I'm sorry, but my AI brain is not configured right now. Please contact support.",
   206|      ok: false,
   207|      error: 'AI not configured',
   208|      turnCount: 0,
   209|      hadContext: false,
   210|      topicDetected: null,
   211|      durationMs: Date.now() - start,
   212|    };
   213|  }
   214|
   215|  const callSid = opts.callSid || `anon-${Date.now()}`;
   216|  const session = getOrCreateSession(callSid);
   217|  const hadContext = session.turns.length > 0;
   218|
   219|  // Build conversation context from prior turns
   220|  const contextTurns = session.turns.slice(-MAX_CONTEXT_TURNS);
   221|  const messages = contextTurns.map((turn) => ({
   222|    role: turn.role,
   223|    content: turn.content,
   224|  }));
   225|
   226|  // Add the current question
   227|  messages.push({
   228|    role: 'user' as const,
   229|    content: question,
   230|  });
   231|
   232|  // Build the system prompt with conversation context summary
   233|  let systemPrompt = SMART_VOICE_SYSTEM_PROMPT;
   234|
   235|  if (hadContext) {
   236|    const turnSummary = contextTurns
   237|      .map((t, i) => `${t.role === 'user' ? 'Caller' : 'You'}: ${t.content}`)
   238|      .join('\n');
   239|    systemPrompt += `\n\n--- CONVERSATION HISTORY (so far) ---\n${turnSummary}\n--- END HISTORY ---\n\nThe caller just asked a new question. Use the conversation history above to maintain continuity. If they're following up on something, reference it. Respond naturally as if continuing the conversation.`;
   240|  } else {
   241|    systemPrompt += `\n\nThis is the FIRST question in the conversation. Greet naturally if appropriate, then answer.`;
   242|  }
   243|
   244|  // Detect topic (simple keyword-based for context tracking)
   245|  const topicDetected = detectTopic(question);
   246|
   247|  try {
   248|    const result = await requestIVXAIText({
   249|      module: 'smart-voice-call' as never,
   250|      system: systemPrompt,
   251|      messages,
   252|      maxOutputTokens: 300,
   253|    });
   254|
   255|    const answer = (result.text || '').trim();
   256|    if (!answer) {
   257|      return {
   258|        answer: "I'm not sure how to answer that. Could you try rephrasing?",
   259|        ok: false,
   260|        error: 'Empty AI response',
   261|        turnCount: session.totalTurns,
   262|        hadContext,
   263|        topicDetected,
   264|        durationMs: Date.now() - start,
   265|      };
   266|    }
   267|
   268|    // Record this turn in the conversation history
   269|    session.totalTurns += 1;
   270|    session.turns.push({
   271|      role: 'user',
   272|      content: question,
   273|      timestamp: Date.now(),
   274|      turnIndex: session.totalTurns,
   275|    });
   276|    session.turns.push({
   277|      role: 'assistant',
   278|      content: answer,
   279|      timestamp: Date.now(),
   280|      turnIndex: session.totalTurns,
   281|    });
   282|    session.lastActivityAt = Date.now();
   283|
   284|    // Track topic context
   285|    if (topicDetected) {
   286|      session.topicContext = topicDetected;
   287|    }
   288|
   289|    // Trim turns if exceeding max
   290|    if (session.turns.length > MAX_TURNS_PER_SESSION * 2) {
   291|      session.turns = session.turns.slice(-MAX_TURNS_PER_SESSION);
   292|    }
   293|
   294|    console.log(`[IVX Voice Brain] CallSid: ${callSid}, turn: ${session.totalTurns}, hadContext: ${hadContext}, topic: ${topicDetected || 'none'}, answer length: ${answer.length}`);
   295|
   296|    return {
   297|      answer,
   298|      ok: true,
   299|      error: null,
   300|      turnCount: session.totalTurns,
   301|      hadContext,
   302|      topicDetected,
   303|      durationMs: Date.now() - start,
   304|    };
   305|  } catch (err) {
   306|    const errorMsg = err instanceof Error ? err.message : String(err);
   307|    console.error('[IVX Voice Brain] AI brain error:', errorMsg);
   308|    return {
   309|      answer: "I apologize, I'm having trouble processing that right now. Please try again.",
   310|      ok: false,
   311|      error: errorMsg,
   312|      turnCount: session.totalTurns,
   313|      hadContext,
   314|      topicDetected,
   315|      durationMs: Date.now() - start,
   316|    };
   317|  }
   318|}
   319|
   320|// ── Topic detection ───────────────────────────────────────────────────────────
   321|
   322|/**
   323| * Simple topic detection for context tracking.
   324| * Helps the brain maintain conversational continuity.
   325| */
   326|function detectTopic(text: string): string | null {
   327|  const lower = text.toLowerCase();
   328|
   329|  const topics: Array<{ keywords: string[]; topic: string }> = [
   330|    { keywords: ['ivx', 'holdings', 'agent', 'division', '112', 'autonomous'], topic: 'ivx_company' },
   331|    { keywords: ['code', 'code execution', 'typescript', 'kotlin', 'swift', 'architecture', 'backend', 'frontend'], topic: 'tech_architecture' },
   332|    { keywords: ['deploy', 'render', 'github', 'ci', 'cd', 'pipeline', 'build'], topic: 'deployment' },
   333|    { keywords: ['android', 'app', 'mobile', 'compose', 'ktor'], topic: 'android_app' },
   334|    { keywords: ['voice', 'call', 'signalwire', 'phone', 'sms'], topic: 'voice_communication' },
   335|    { keywords: ['ai', 'gpt', 'model', 'brain', 'gpt-4o', 'gateway'], topic: 'ai_brain' },
   336|    { keywords: ['supabase', 'database', 'data', 'table', 'query'], topic: 'database' },
   337|    { keywords: ['weather', 'news', 'today', 'current'], topic: 'general_knowledge' },
   338|    { keywords: ['code', 'function', 'bug', 'error', 'debug', 'fix'], topic: 'coding_help' },
   339|    { keywords: ['business', 'revenue', 'money', 'cost', 'price', 'market'], topic: 'business' },
   340|  ];
   341|
   342|  for (const { keywords, topic } of topics) {
   343|    if (keywords.some((kw) => lower.includes(kw))) {
   344|      return topic;
   345|    }
   346|  }
   347|
   348|  return null;
   349|}
   350|
   351|// ── Conversation summary (for status/debug) ───────────────────────────────────
   352|
   353|/**
   354| * Get a summary of the conversation for a given CallSid.
   355| * Used by status endpoints and debugging.
   356| */
   357|export function getConversationSummary(callSid: string): {
   358|  callSid: string;
   359|  totalTurns: number;
   360|  durationMs: number;
   361|  topicContext: string | null;
   362|  lastUserQuestion: string | null;
   363|  lastAssistantAnswer: string | null;
   364|} | null {
   365|  const session = sessions.get(callSid);
   366|  if (!session) return null;
   367|
   368|  const lastUser = [...session.turns].reverse().find((t) => t.role === 'user');
   369|  const lastAssistant = [...session.turns].reverse().find((t) => t.role === 'assistant');
   370|
   371|  return {
   372|    callSid,
   373|    totalTurns: session.totalTurns,
   374|    durationMs: Date.now() - session.startedAt,
   375|    topicContext: session.topicContext,
   376|    lastUserQuestion: lastUser?.content ?? null,
   377|    lastAssistantAnswer: lastAssistant?.content ?? null,
   378|  };
   379|}
   380|
   381|// ── Brain status ──────────────────────────────────────────────────────────────
   382|
   383|export function getVoiceBrainStatus(): {
   384|  marker: string;
   385|  version: string;
   386|  activeConversations: number;
   387|  totalTurns: number;
   388|  maxContextTurns: number;
   389|  sessionTtlMinutes: number;
   390|  aiConfigured: boolean;
   391|} {
   392|  const stats = getActiveSessionStats();
   393|  return {
   394|    marker: IVX_VOICE_BRAIN_MARKER,
   395|    version: IVX_VOICE_BRAIN_VERSION,
   396|    activeConversations: stats.activeSessions,
   397|    totalTurns: stats.totalTurns,
   398|    maxContextTurns: MAX_CONTEXT_TURNS,
   399|    sessionTtlMinutes: SESSION_TTL_MS / 60_000,
   400|    aiConfigured: isIVXAIConfigured(),
   401|  };
   402|}

