   594|export async function requestIVXAIText(input: {
   595|  module: IVXAIModule;
   596|  requestId?: string | null;
   597|  model?: string | null;
   598|  system?: string | null;
   599|  prompt?: string | null;
   600|  messages?: IVXAITextMessage[];
   601|  images?: IVXAIImageAttachment[];
   602|  files?: IVXAIFileAttachment[];
   603|  maxOutputTokens?: number;
   604|  /** V6.19: Optional AbortSignal — when aborted, the underlying generateText
   605|   * call is cancelled immediately via the Vercel AI SDK's abortSignal param.
   606|   * This is the real cancellation path (Promise.race does NOT cancel the HTTP
   607|   * request — only abortSignal does). */
   608|  abortSignal?: AbortSignal | null;
   609|}): Promise<IVXAITextResult> {
   610|  const dedupKey = readTrimmed(input.requestId) ? `${String(input.module)}::${readTrimmed(input.requestId)}` : null;
   611|  if (dedupKey) {
   612|    const existing = inFlightAIRequests.get(dedupKey);
   613|    if (existing) {
   614|      console.log('[IVXAI] Duplicate in-flight request deduplicated (idempotency guard):', {
   615|        module: input.module,
   616|        requestId: input.requestId ?? null,
   617|      });
   618|      return existing;
   619|    }
   620|  }
   621|  const pending = requestIVXAITextInternal(input);
   622|  if (dedupKey) {
   623|    inFlightAIRequests.set(dedupKey, pending);
   624|    pending.catch(() => undefined).finally(() => inFlightAIRequests.delete(dedupKey));
   625|  }
   626|  return pending;
   627|}
