   629|async function requestIVXAITextInternal(input: {
   630|  module: IVXAIModule;
   631|  requestId?: string | null;
   632|  model?: string | null;
   633|  system?: string | null;
   634|  prompt?: string | null;
   635|  messages?: IVXAITextMessage[];
   636|  images?: IVXAIImageAttachment[];
   637|  files?: IVXAIFileAttachment[];
   638|  maxOutputTokens?: number;
