   640|}): Promise<IVXAITextResult> {
   641|  const model = resolveIVXAIModel(input.model);
   642|  const endpoint = getIVXAIEndpoint(model);
   643|  const messages = normalizeMessages(input.messages);
   644|  const prompt = readTrimmed(input.prompt);
   645|  const system = readTrimmed(input.system);
   646|  const images = (input.images ?? [])
   647|    .map((img) => ({ url: readTrimmed(img.url), mimeType: readTrimmed(img.mimeType ?? '') || null }))
   648|    .filter((img) => img.url.length > 0);
   649|  const files = (input.files ?? []).filter(
   650|    (file) => readTrimmed(file.mediaType).length > 0 && file.data != null,
   651|  );
   652|
   653|  if (!prompt && messages.length === 0) {
   654|    throw new Error('IVX AI request requires a prompt or messages.');
   655|  }
