   657|  const baseUrlCandidates = getGatewayBaseUrlCandidates();
   658|  if (baseUrlCandidates.length === 0) {
   659|    throw new Error('IVX AI runtime is not configured.');
   660|  }
   661|
   662|  console.log('[IVXAI] Routing request through IVX AI Phase 1 wrapper:', {
   663|    module: input.module,
   664|    requestId: input.requestId ?? null,
   665|    model,
   666|    endpoint,
   667|    baseUrlCandidates,
   668|    hasSystem: system.length > 0,
   669|    promptLength: prompt.length,
   670|    messageCount: messages.length,
   671|    authKeySource: 'OPENAI_API_KEY',
   672|    requestShape: messages.length > 0 ? 'messages' : 'prompt',
   673|    maxOutputTokens: input.maxOutputTokens ?? null,
   674|    phase: 'agent_runtime_v2',
   675|    layer: 'ivx_ai_runtime_wrapper',
   676|  });
   677|
   678|  // When a live stream callback is set in AsyncLocalStorage context (e.g. from
   679|  // the owner AI SSE handler), route through streamIVXAIText which yields token
   680|  // deltas in real time. streamIVXAIText manages its own queue slot, timeout,
   681|  // and telemetry, so we return early before the non-streaming generateText path.
   682|  const streamCallback = getOwnerAIStreamCallback();
   683|  if (streamCallback) {
   684|    let accumulated = '';
   685|    let streamUsage: unknown = null;
   686|    let streamProviderMetadata: IVXAIProviderMetadata | null = null;
   687|    let streamError: string | null = null;
   688|    for await (const chunk of streamIVXAIText(input)) {
   689|      if (chunk.type === 'delta' && chunk.delta) {
   690|        accumulated += chunk.delta;
   691|        streamCallback(chunk.delta);
   692|      } else if (chunk.type === 'done') {
   693|        accumulated = chunk.text ?? accumulated;
   694|        streamUsage = chunk.usage ?? null;
   695|        streamProviderMetadata = chunk.providerMetadata ?? null;
   696|        if ('error' in chunk && chunk.error) streamError = chunk.error as string;
   697|      } else if (chunk.type === 'error') {
   698|        streamError = chunk.error ?? 'IVX AI stream failed';
   699|      }
   700|    }
   701|    if (streamError) {
   702|      throw new Error(streamError);
   703|    }
   704|    const text = readTrimmed(accumulated);
   705|    if (!text) {
   706|      throw new Error('IVX AI stream returned an empty response.');
   707|    }
   708|    const providerMetadata: IVXAIProviderMetadata = streamProviderMetadata ?? {
   709|      provider: 'chatgpt',
   710|      source: 'remote_api',
   711|      model,
   712|      endpoint: baseUrlCandidates[0] ?? null,
   713|      runtime: 'ivx_ai_gateway',
   714|      ivxAI: {
   715|        architecture: 'ivx-ai',
   716|        phase: 'agent_runtime_v2',
   717|        layer: 'ivx_ai_runtime_wrapper',
   718|        module: input.module,
   719|        providerDependency: 'chatgpt_current_baseline',
   720|        requestId: input.requestId ?? null,
